int shared_counter = 0;

void modify_unsafe() {
    // Read-Modify-Write cycle is not atomic
    for (int i = 0; i < 10000; ++i) {
        shared_counter++;
    }
}

// Two threads accessing shared_counter simultaneously
std::thread t1(modify_unsafe);
std::thread t2(modify_unsafe);

t1.join();
t2.join();

// shared_counter is unpredictable (usually < 20000)
// The result depends purely on thread scheduling timing.
